return {
    stringToNumber = function(p1, p2) -- stringToNumber | line: 1
        if not p2 or type(p2) ~= "string" then
            error("stringToNumber had invalid parameters.\nP1 - string: string", 2)
        end

        local n1 = 1
        local v1 = p2

        for v2, v3 in pairs(p1._suffixTable) do
            v1 = string.gsub(v1, v3, function() -- line: 9
                -- upvalues: n1 (ref), v2 (copy)
                n1 *= 10 ^ (v2 * 3)

                return ""
            end)
        end

        if not tonumber(v1) then
            error("stringToNumber invalid parameter #1: Expected a string which could be converted to a number, got \"" .. v1 .. "\"", 2)
        end

        return n1 * v1
    end
}
